using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Lean81;

static partial class Tests
{
    static void NativeResourceProbe()
    {
        Assert(Environment.GetEnvironmentVariable("LEAN81_NATIVE_FIXTURES") == "ephemeral-ci" && Environment.OSVersion.Platform == PlatformID.Win32NT && IntPtr.Size == 4, "resource ABI probe requires explicitly opted-in x86 Windows CI");
        var capture = CpuCapture.Run(4, System.Threading.CancellationToken.None, null);
        Assert(capture.Error == null && capture.Samples.Count >= 2 && capture.MemoryBytes > 0);
        Assert(capture.Samples.All(s => ResourceAnalysis.Number(s.metrics, "commit_bytes").HasValue && ResourceAnalysis.Number(s.metrics, "commit_limit_bytes").HasValue && ResourceAnalysis.Number(s.metrics, "kernel_nonpaged_bytes").HasValue));
        Assert(capture.Samples.All(s => s.processes.Count <= 20 && (!s.metrics.ContainsKey("disk_busy_pct") || s.metrics["disk_busy_pct"] == null || ResourceAnalysis.Number(s.metrics, "disk_busy_pct", 100).HasValue)));
        Assert(capture.Samples.SelectMany(s => s.processes).Any(p => p.io_bytes_per_sec.HasValue && p.private_bytes.HasValue));
        Assert(capture.Samples.Any(s => ResourceAnalysis.Number(s.metrics, "disk_busy_pct", 100).HasValue), "Expected installed PhysicalDisk counters on the Windows CI image");
    }
    static ItemState Desktop(bool present = false, int value = 1)
    { return new ItemState { Kind = "setting", Scope = "user", Target = "taskbar-animation", Exists = true, Enabled = !present || value != 0, ValueKind = present ? 4 : 0, Value = present ? value.ToString(System.Globalization.CultureInfo.InvariantCulture) : null }; }
    static void ResourceTests()
    {
        Test("old workspace profiles keep newly introduced features", () => { var p = Product.Json().Deserialize<UsageProfile>("{\"Printing\":false,\"Prefetch\":false}"); Assert(!p.Printing && !p.Prefetch && p.Scanning && p.PortableDevices && p.ErrorReporting && p.LinkTracking); });
        Test("browser preset keeps printing Bluetooth search and preloading", () => { var p = Profiles.Preset(3); Assert(p.Printing && p.Bluetooth && p.IndexedSearch && p.Prefetch && p.ErrorReporting && !p.HomeGroup && !p.Scanning && !p.PortableDevices && !p.LinkTracking && !p.TouchKeyboard); });
        Test("profile copy preserves every new answer", () => { var p = new UsageProfile(); Profiles.Copy(Unused(), p); Assert(!p.Scanning && !p.PortableDevices && !p.ErrorReporting && !p.LinkTracking); });
        Test("new service options require their explicit unused feature", () => { foreach (string name in new[] { "stisvc", "WpdBusEnum", "WerSvc", "TrkWks" }) { Throws(() => Policy.Validate(Service(name), new UsageProfile(), false)); Policy.Validate(Service(name), Unused(), false); } });
        Test("new service dependencies are still protected", () => { var s = Service("stisvc"); s.Dependents = new[] { "Fixture dependent" }; Throws(() => Policy.Validate(s, Unused(), false)); });
        Test("desktop missing DWORD can be reduced and exactly recovered", () => { var s = Desktop(); var b = new Fake(s); var j = new MemoryJournals(); var e = new ChangeEngine(b, j); var r = e.Apply(new[] { Item(s) }, new UsageProfile(), null); Assert(r.Status == "Applied" && b.Read(s).Value == "0" && b.Read(s).ValueKind == 4); Assert(e.Restore(r.Id, null).Status == "Restored" && b.Read(s).Value == null && b.Read(s).ValueKind == 0); });
        Test("desktop existing signed DWORD round trips exactly", () => { var s = Desktop(true, -1); var b = new Fake(s); var e = new ChangeEngine(b, new MemoryJournals()); var r = e.Apply(new[] { Item(s) }, new UsageProfile(), null); Assert(r.Status == "Applied" && e.Restore(r.Id, null).Status == "Restored" && b.Read(s).Fingerprint() == s.Fingerprint()); });
        Test("desktop receipt passes persisted validation", () => { var s = Desktop(); var b = new Fake(s); var r = new ChangeEngine(b, new MemoryJournals()).Apply(new[] { Item(s) }, new UsageProfile(), null); ChangeEngine.ValidateReceipt(r, b.MachineScope); });
        Test("desktop independent edits stop whole-batch restore", () => { var s = Desktop(); var b = new Fake(s); var j = new MemoryJournals(); var e = new ChangeEngine(b, j); var r = e.Apply(new[] { Item(s) }, new UsageProfile(), null); b.States[s.Identity()].Value = "2"; b.States[s.Identity()].Enabled = true; Throws(() => e.Restore(r.Id, null)); Assert(b.Writes == 1); });
        Test("arbitrary desktop value identifiers are refused", () => { var s = Desktop(); s.Target = "DisableSecurity"; Throws(() => Policy.Validate(s, Unused(), false)); });
        Test("desktop machine scope is refused", () => { var s = Desktop(); s.Scope = "machine"; Throws(() => Policy.Validate(s, Unused(), false)); });
        Test("desktop nonexistent key is refused", () => { var s = Desktop(); s.Exists = false; Throws(() => Policy.Validate(s, Unused(), false)); });
        Test("desktop string binary and malformed DWORD are refused", () => { foreach (int kind in new[] { 1, 2, 3, 7, 11 }) { var s = Desktop(true); s.ValueKind = kind; Throws(() => Policy.Validate(s, Unused(), false)); } var bad = Desktop(true); bad.Value = "not an integer"; Throws(() => Policy.Validate(bad, Unused(), false)); });
        Test("desktop state must agree with actual DWORD", () => { var s = Desktop(true, 0); s.Enabled = true; Throws(() => Policy.Validate(s, Unused(), false)); });
        Test("desktop unexpected missing-value payload is refused", () => { var s = Desktop(); s.Value = "1"; Throws(() => Policy.Validate(s, Unused(), false)); });
        Test("desktop Peek uses the DWM location and other effects use Explorer Advanced", () => { Assert(DesktopSettings.Options.Single(o => o.Id == "desktop-peek").KeyPath == @"Software\Microsoft\Windows\DWM"); Assert(DesktopSettings.Options.Where(o => o.Id != "desktop-peek").All(o => o.KeyPath == @"Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced")); });
        Test("quick tune never includes startup or task entries", () => { var profile = Unused(); var scan = new DemoBackend().Scan(profile); var plan = TuningPlan.Build(scan, profile, false); Assert(plan.Count > 0 && plan.All(x => x.Kind == "service")); });
        Test("quick tune effects require a separate opt-in", () => { var p = Profiles.Preset(3); var scan = new DemoBackend().Scan(p); Assert(!TuningPlan.Build(scan, p, false).Any(x => x.Kind == "setting") && TuningPlan.Build(scan, p, true).Count(x => x.Kind == "setting") == 3); });
        Test("quick tune rechecks usage policy even for stale selectable flags", () => { var scan = new DemoBackend().Scan(Unused()); Assert(TuningPlan.Build(scan, new UsageProfile(), false).Count == 0); });
        Test("quick tune is read only and leaves input state untouched", () => { var p = Unused(); var scan = new DemoBackend().Scan(p); string before = Product.Json().Serialize(scan); TuningPlan.Build(scan, p, true); Assert(before == Product.Json().Serialize(scan)); });
        Test("resource missing booleans strings and nonfinite numbers remain unknown", () => { var m = new Dictionary<string, object> { { "null", null }, { "string", "5" }, { "bool", true }, { "nan", Double.NaN }, { "negative", -1 }, { "too-high", 101.0 } }; Assert(new[] { "absent", "null", "string", "bool", "nan", "negative", "too-high" }.All(k => !ResourceAnalysis.Number(m, k, 100).HasValue)); });
        Test("resource average weights valid intervals and excludes missing counters", () => { var c = CaptureResult.Demo(); c.Samples = c.Samples.Take(3).ToList(); c.Samples[0].dt = 1; c.Samples[0].metrics["disk_busy_pct"] = 10.0; c.Samples[1].dt = 3; c.Samples[1].metrics["disk_busy_pct"] = 90.0; c.Samples[2].metrics["disk_busy_pct"] = null; Assert(ResourceAnalysis.Average(c, "disk_busy_pct") == 70); });
        Test("resource process leaders retain idle memory-heavy processes", () => { var p = Enumerable.Range(1, 40).Select(i => new ProcessReading { pid = i, name = "p" + i, cpu_pct = i, rss_bytes = i == 1 ? 9000000000L : 1024, private_bytes = 1024, io_bytes_per_sec = i == 2 ? (double?)999999999 : null }).ToArray(); var leaders = CpuCapture.SelectLeaders(p); Assert(leaders.Count <= 20 && leaders.Any(x => x.pid == 1 && x.cpu_pct == 1) && leaders.Any(x => x.pid == 2) && leaders.Any(x => x.pid == 40)); });
        Test("resource process leaders are deduplicated", () => { var p = Enumerable.Range(1, 5).Select(i => new ProcessReading { pid = i, cpu_pct = i, rss_bytes = i, private_bytes = i, io_bytes_per_sec = i }); Assert(CpuCapture.SelectLeaders(p).Count == 5); });
        Test("process PID reuse remains separate in analysis", () => { var c = CaptureResult.Demo(); c.Samples[1].processes[0].started_ticks = 2; Assert(ResourceAnalysis.Processes(c).Count(p => p.Pid == 120) == 2); });
        Test("resource findings report memory commit and disk pressure", () => { var c = CaptureResult.Demo(); foreach (var s in c.Samples) { s.metrics["memory_available_pct"] = 4.0; s.metrics["disk_busy_pct"] = 95.0; s.metrics["commit_pct"] = 95.0; } var text = ResourceAnalysis.Findings(c); Assert(text.Contains("Low available RAM") && text.Contains("near its limit") && text.Contains("High aggregate") && text.Contains("network/device")); });
        Test("missing disk readings never claim idle disk", () => { var c = CaptureResult.Demo(); foreach (var s in c.Samples) s.metrics["disk_busy_pct"] = null; var text = ResourceAnalysis.Findings(c); Assert(text.Contains("not 0%") && !text.Contains("No sustained")); });
        Test("v1 summary includes disk coverage commit and nonpaged memory", () => { var s = Summary(); Assert(s.AverageDiskBusy.HasValue && s.PeakCommit == 56 && s.ValidDiskSamples == s.Samples && s.ValidCommitSamples == s.Samples && s.PeakNonpagedBytes > 0); });
        Test("legacy summaries without resource fields still load", () => { var s = Summary(); s.AverageDiskBusy = s.PeakCommit = s.PeakNonpagedBytes = null; s.ValidDiskSamples = s.ValidCommitSamples = 0; CaptureSummary.Validate(s); Assert(!CaptureComparison.Compare(s, Summary()).DiskDifference.HasValue); });
        Test("invalid new resource summary fields are refused", () => { var s = Summary(); s.PeakCommit = Double.NaN; Throws(() => CaptureSummary.Validate(s)); s = Summary(); s.ValidDiskSamples = s.Samples + 1; Throws(() => CaptureSummary.Validate(s)); s = Summary(); s.ValidDiskSamples = 0; Throws(() => CaptureSummary.Validate(s)); });
        Test("incomplete disk coverage cannot produce a disk comparison", () => { var a = Summary(); var b = Summary(); b.ValidDiskSamples--; Assert(CaptureComparison.Compare(a, b).Comparable && !CaptureComparison.Compare(a, b).DiskDifference.HasValue); });
        Test("compatible resource captures show disk percentage point changes", () => { var a = Summary(); var b = Summary(); b.AverageDiskBusy -= 10; var delta = CaptureComparison.Compare(a, b); Assert(delta.Comparable && delta.DiskDifference == -10 && delta.Text().Contains("Aggregate disk busy")); });
        Test("v1 report includes resource metrics without process names", () => { var text = Reports.Build(new DemoBackend().Scan(Unused()), DeviceSnapshot.Demo(), Summary(), false, true); Assert(text.Contains("physical-disk busy") && text.Contains("nonpaged kernel pool") && text.Contains("commit limit") && !text.Contains("IdleMemoryApp")); });
        Test("v1 CSV exports new numbers and keeps process names redacted", () => { var path = Path.GetTempFileName(); try { CaptureResult.Demo().ExportCsv(path, false); var text = File.ReadAllText(path); Assert(text.Contains("disk_busy_pct") && text.Contains("commit_pct") && !text.Contains("ExampleApp") && !text.Contains("IdleMemoryApp")); } finally { File.Delete(path); } });
        Test("v1 trace includes I/O scope and memory metrics", () => { var path = Path.GetTempFileName(); try { CaptureResult.Demo().Export(path, false); var text = File.ReadAllText(path); Assert(text.Contains("io_bytes_per_sec") && text.Contains("private_bytes") && text.Contains("not just disk") && !text.Contains("ExampleApp") && !text.Contains("IdleMemoryApp")); } finally { File.Delete(path); } });
    }
}
